css:
/* Feature split: a heading, copy and a button beside a photograph. Rows alternate: the first has the photo on
   the right, the second on the left (on a pale panel), and so on. */
[data-bz-node^="fs-band"] { background: #fff; }
[data-bz-node^="fs-band"] > .bz-container { max-width: min(90vw, 1440px); }
[data-bz-section="feature-split"] .bz-block { padding-block: 0; }
[data-bz-node^="fs-row"] { align-items: center; }
[data-bz-node^="fs-copy"] { padding: 0 40px 0 24px; }
[data-bz-section="feature-split"] h2 { margin: 0 0 22px; font: 700 1.9rem / 1.2 var(--font-heading); color: #000; letter-spacing: 0; }
[data-bz-node^="fs-text"] .bz-text p { margin: 0 0 14px; font: 400 0.8rem / 1.7 var(--font-body); color: #000; max-width: none; }
[data-bz-node^="fs-cta"] { margin-top: 24px; }
[data-bz-node^="fs-cta"] .bz-btn { height: 41px; padding: 0 22px; border-radius: 0; font: 700 0.85rem / 41px var(--font-body); background: var(--accent); color: #fff; }
[data-bz-node^="fs-media"] .bz-figure { margin: 0; }
[data-bz-node^="fs-media"] img { display: block; width: 100%; height: auto; border-radius: 0; }
[data-bz-node="fs-band-1"], [data-bz-node="fs-band-3"] { padding-block: 72px 48px; }
[data-bz-node="fs-band-3"] { padding-block: 72px 48px; }
[data-bz-node="fs-band-2"] > .bz-container { background: #ebf7ff; padding: 30px 0 30px 30px; }
[data-bz-node="fs-band-2"] { padding-block: 30px 0; }
[data-bz-node="fs-band-2"] [data-bz-node^="fs-row"] > [data-bz-node^="fs-copy"] { order: 2; padding: 0 70px 0 60px; }
[data-bz-node="fs-band-2"] [data-bz-node^="fs-row"] > [data-bz-node^="fs-media"] { order: 1; }
@media (max-width: 1100px) { [data-bz-node^="fs-copy"], [data-bz-node="fs-band-2"] [data-bz-node^="fs-row"] > [data-bz-node^="fs-copy"] { padding: 24px; order: 2; } [data-bz-node^="fs-media"] { order: 1; } [data-bz-node^="fs-band"] { padding-block: 32px 0 !important; } [data-bz-node="fs-band-2"] > .bz-container { padding: 0; } }
